    FROM (
        SELECT __loaded_at FROM {{ ref('sat_customer_details') }}
        UNION ALL
        SELECT __loaded_at FROM {{ ref('sat_customer_tracking') }}
    ) AS loads
),
keys AS (
    SELECT customer_hk
